import {createClient} from '@supabase/supabase-js';
import {AUTH_URL,AUTH_KEY,seed,uid,groups,calculate,completionRows,csv,cleanCourse} from './model.js';
import {demoCall,resetDemo} from './demo.js';
const auth=createClient(AUTH_URL,AUTH_KEY,{auth:{storageKey:'mayne-lms-auth'}});
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
let session=null,demo=new URLSearchParams(location.search).has('demo'),courses=[],data=null,page='Home',itemId=null,preview=null,instructor=false,gradeStudent=null,gradeItem=null,timer=null,busy=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(label,action,args='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${args}>${label}</button>`;
const badge=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const fmt=x=>x?new Date(x).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'No due date';
const percent=x=>x===null||x===undefined?'—':x.toFixed(1)+'%';
const student=()=>data?.enrollments.find(e=>e.id===data.me);
const sub=(i,e=data.me)=>data.submissions.find(s=>s.item_id===i&&s.enrollment_id===e);
const state=e=>e.summary||calculate(data,e.id);
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>el.style.display='none',6500);}
function dialog(title,html,onSubmit){modal.innerHTML=`<form id="modal-form"><div class="modal-head"><h2>${esc(title)}</h2>${b('✕','close-modal','aria-label="Close dialog"')}</div>${html}<div class="modal-actions">${b('Cancel','close-modal')}<button class="primary" type="submit">Save</button></div></form>`;modal.showModal();modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const submit=ev.submitter;submit.disabled=true;try{await onSubmit(new FormData(ev.target));modal.close();}catch(e){toast(e.message);}finally{submit.disabled=false;}};}
async function call(action,p={}){if(demo)return demoCall(action,p);if(!session)throw Error('Sign in first.');const {data:s,error}=await auth.auth.getSession();if(error||!s.session)throw Error('Your session expired. Sign in again.');session=s.session;const r=await fetch('/api/lms',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({action,payload:p})});if(!r.ok){const d=await r.json();throw Error(d.error||'Unable to complete action.');}if(action.endsWith('-csv'))return {text:await r.text()};return r.json();}
async function mutation(action,p={}){data=await call(action,{course:data.course.id,...(preview?{preview}:{}),...p});render();}
async function loadList(){const r=await call('list');courses=r.courses;instructor=r.instructor;data=null;preview=null;gradeItem=null;gradeStudent=null;page='Home';render();}
async function openCourse(id){data=await call('get',{course:id});preview=null;gradeItem=null;gradeStudent=null;page='Home';itemId=null;render();}
async function reload(){if(data)data=await call('get',{course:data.course.id,...(preview?{preview}:{})});else return loadList();render();}
function login(){app.innerHTML=`<div class="login"><div class="intro"><div class="eyebrow">MAYNE LEADERSHIP · LEARNING STUDIO</div><h1>Your classroom.<br>Your learning.<br>Your next step.</h1><p class="muted" style="margin-top:22px">A dedicated space for lectures, conversations, assignments, and assessment—with feedback that moves learning forward.</p><div class="row">${badge('Classes of up to 20')}${badge('Connected gradebook')}${badge('Completion exports')}</div><div class="notice" style="margin-top:25px">Try the full course workflow with fictional students before opening your first class.</div>${b('Explore the pilot classroom →','demo','','primary')}</div><div class="panel"><h2>Welcome back</h2><p class="muted">Use your individual learning account. Instructors use the same account as Leadership Challenge Studio.</p><form id="login-form"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="username"><label for="password">Password</label><input id="password" name="password" type="password" required minlength="8" autocomplete="current-password"><button type="submit" class="primary" style="width:100%;margin-top:20px">Sign in</button></form><div class="pill-nav">${b('Create account','signup')}${b('Forgot password','forgot')}</div><p id="auth-status" role="status" class="muted"></p><small>Student access is limited to classes where the instructor has enrolled your email address.</small><p style="margin-top:20px"><a href="/index.html">← Mayne Leadership</a></p></div></div>`;document.querySelector('#login-form').onsubmit=async ev=>{ev.preventDefault();ev.submitter.disabled=true;const f=new FormData(ev.target);try{const {data:d,error}=await auth.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error)throw error;session=d.session;await loadList();}catch(e){document.querySelector('#auth-status').textContent=e.message;}finally{ev.submitter.disabled=false;}};}
function render(){clearInterval(timer);if(!demo&&!session)return login();const c=data?.course;const nav=data?['Home','Modules','Lectures','Assignments','Discussions','Quizzes','Grades',...(data.instructor?['People','Completion','Settings']:[])]:[];app.innerHTML=`<nav class="global" aria-label="Global navigation"><a href="/index.html"><span class="monogram">JM</span></a>${b('▦<br>Dashboard','dashboard')}<a href="/learning.html">◈<br>Learning</a><div class="bottom">${b('↪<br>Sign out','logout')}</div></nav><div class="shell"><header class="top"><div class="breadcrumb">${b('Learning Studio','dashboard')} ${c?' / '+esc(c.data.code||'Course')+' / '+esc(page):''}</div><div class="top-actions">${data&&data.instructor?b('Student view','preview'):preview?b('Leave student view','leave-preview','','primary'):''}${b('Refresh','refresh')}<span class="tag">${demo?'Pilot preview':data?.instructor||instructor?'Instructor':'Student'}</span></div></header>${demo?`<div class="banner">PILOT PREVIEW · Fictional students and work are saved only in this browser. ${b('Connect to live classroom','exit-demo')} ${b('Reset pilot','reset-demo')}</div>`:''}${preview?`<div class="banner">Student view · ${esc(student()?.name)} · Changes are saved to this student’s class record.</div>`:''}${data?`<div class="course-layout"><nav class="course-nav" aria-label="Course navigation"><h3>${esc(c.name)}<br><small>${esc(c.data.code)}</small></h3>${nav.map(n=>b(n,'page',`data-page="${n}"`,page===n?'active':'')).join('')}</nav><main id="main" class="content">${content()}</main></div>`:`<main id="main" class="dashboard">${dashboard()}</main>`}</div>`;
if(page==='Quizzes'&&itemId)startTimer();}
function dashboard(){return `<div class="title-row"><div><div class="eyebrow">YOUR LEARNING SPACE</div><h1>Dashboard</h1><p class="muted">${instructor?'Create a classroom, prepare your course, and guide your learners.':'Select a class to view your learning activities.'}</p></div>${instructor?b('+ Create class','create','','primary'):''}</div><div class="grid">${courses.map(c=>`<article class="card course"><div class="row">${badge(c.code||'COURSE')}${badge(c.published?'Published':'Unpublished',c.published?'green':'gold')}</div><h2>${esc(c.title)}</h2><p>${esc(c.name)}</p><p class="muted">${esc(c.description)}</p><p><small>${c.students} / 20 students</small></p>${b('Enter classroom →','open',`data-id="${c.id}"`,'primary')}</article>`).join('')||'<div class="empty">No classes yet. '+(instructor?'Create your first class using the Critical Thinking pilot template.':'Ask your instructor to enroll the email you used to sign in.')+'</div>'}</div>`;}
function heading(title,description,actions=''){return `<div class="title-row"><div><h1>${esc(title)}</h1><p class="muted">${esc(description)}</p></div><div class="actions">${actions}</div></div>`;}
function itemStatus(i,e=data.me){const s=sub(i.id,e);if(i.type==='lecture')return data.views.some(v=>v.item_id===i.id&&v.enrollment_id===e)?badge('Viewed','green'):badge('To read');if(s?.status==='excused')return badge('Excused');if(s?.score!==null&&s?.score!==undefined&&s.posted)return badge(s.score+' / '+i.points,'green');if(s?.status==='graded')return badge('Grade held','gold');if(s?.status==='submitted')return badge('Submitted','gold');if(s?.status==='draft')return badge('Draft');return i.due&&Date.now()>Date.parse(i.due)?badge('Missing','red'):badge('Not submitted');}
const icons={lecture:'▤',assignment:'▧',discussion:'◌',quiz:'◇'};
function itemRow(i){return `<div class="list-item"><span class="icon">${icons[i.type]}</span><div class="body">${b(esc(i.title),'item',`data-id="${i.id}"`,'link')}<small>${i.type==='lecture'?'Reading & lecture':i.points+' pts · '+fmt(i.due)} ${i.required?' · Required':''}</small></div>${data.instructor?`${badge(i.published?'Published':'Draft',i.published?'green':'gold')}${b('Edit','edit-item',`data-id="${i.id}"`)}`:itemStatus(i)}</div>`;}
function content(){const c=data.course.data,items=c.items;if(page==='Home'){const e=student();const s=e?state(e):null;return `${heading(c.title,data.course.name,data.instructor?b('Edit course','settings-link'):'')}<div class="hero"><div class="eyebrow">${esc(c.code)} · LEADERSHIP LEARNING</div><h2>Welcome to your classroom</h2><p>${esc(c.description)}</p>${b('Start with Modules →','page','data-page="Modules"','primary')}</div><div class="split"><section><h2>Announcements</h2>${c.announcements.map(a=>`<article class="card"><small>${fmt(a.date)}</small><h3 style="margin-top:8px">${esc(a.title)}</h3><div class="prose">${esc(a.body)}</div></article>`).join('')}${data.instructor?b('+ Announcement','announcement'):''}<h2 style="margin-top:25px">Your course at a glance</h2><div class="stats">${[['Lectures',items.filter(i=>i.type==='lecture').length],['Activities',items.filter(i=>i.type!=='lecture'&&i.published).length],[data.instructor?'Enrolled':'Progress',data.instructor?data.enrollments.filter(e=>e.active).length+'/20':s?.progress+'%']].map(([k,v])=>`<div class="stat-box"><small>${k}</small><div class="stat">${v}</div></div>`).join('')}</div></section><aside><div class="panel"><h3>${data.instructor?'Instructor checklist':'Your progress'}</h3>${data.instructor?`<p>1. Review and publish your activities.<br>2. Enroll up to 20 learners.<br>3. Grade submitted work.<br>4. Export completion records.</p>${b('Open gradebook','page','data-page="Grades"')}`:`${badge(s.status.replaceAll('_',' '),s.status==='completed'?'green':'gold')}<div class="progress"><span style="width:${s.progress}%"></span></div><p>${s.done} of ${s.required} required items complete</p><p>Current grade: <strong>${percent(s.current)}</strong></p><p>Passing score: ${c.pass}%</p>`}</div><div class="panel"><h3>To do</h3>${items.filter(i=>i.published&&i.type!=='lecture').slice(0,5).map(i=>`<p>${b(esc(i.title),'item',`data-id="${i.id}"`,'link')}<small>${fmt(i.due)}</small></p>`).join('')}</div></aside></div>`;}
if(page==='Modules')return `${heading('Modules','Follow your learning activities in order.',data.instructor?b('+ Module','module')+' '+b('+ Activity','add-item','','primary'):'')}${c.modules.map(m=>`<section class="module"><div class="module-header"><div><h3>${esc(m.title)}</h3><small>${esc(m.description)}${m.sequential?' · Sequential completion':''}</small></div>${data.instructor?b('Edit','edit-module',`data-id="${m.id}"`):''}</div>${items.filter(i=>i.module===m.id).map(itemRow).join('')||'<div class="empty">No activities in this module.</div>'}</section>`).join('')}`;
if(['Lectures','Assignments','Discussions','Quizzes'].includes(page)){if(itemId)return activity(items.find(i=>i.id===itemId));const type={Lectures:'lecture',Assignments:'assignment',Discussions:'discussion',Quizzes:'quiz'}[page];return `${heading(page,{Lectures:'Readings, resources, and video lectures.',Assignments:'Instructions, submissions, and feedback.',Discussions:'Learn together through thoughtful posts and replies.',Quizzes:'Demonstrate your understanding.'}[page],data.instructor?b('+ Add '+type,'add-item',`data-type="${type}"`,'primary'):'')}<div class="module">${items.filter(i=>i.type===type).map(itemRow).join('')||'<div class="empty">No activities yet.</div>'}</div>`;}
if(page==='Grades')return grades();if(page==='People')return people();if(page==='Completion')return completion();if(page==='Settings')return settings();return '';}
function activity(i){if(!i)return '<div class="empty">Activity unavailable.</div>';const s=sub(i.id),e=student();const before=`${b('← '+page,'back')}<div class="title-row" style="margin-top:22px"><div><h1>${esc(i.title)}</h1><div class="row">${badge(i.type)}${i.type!=='lecture'?badge(i.points+' points'):''}${i.required?badge('Required'):badge('Optional')}${!i.published?badge('Unpublished','gold'):''}</div></div>${data.instructor?b('Edit activity','edit-item',`data-id="${i.id}"`):itemStatus(i)}</div><div class="panel"><h3>Instructions</h3><div class="prose">${esc(i.body)}</div>${i.due?`<p style="margin-top:15px"><strong>Due:</strong> ${fmt(i.due)}</p>`:''}${i.rubric?.length?`<details><summary>Grading rubric</summary>${i.rubric.map(r=>`<p>${esc(r.title)} — ${r.points} points</p>`).join('')}</details>`:''}</div>`;
if(i.type==='lecture'){let video='';if(i.video){try{const u=new URL(i.video);let match=u.hostname==='youtu.be'?u.pathname.slice(1):u.hostname.endsWith('youtube.com')?u.searchParams.get('v'):null;if(match&&/^[\w-]{11}$/.test(match))video=`<iframe class="video" title="Video lecture" src="https://www.youtube-nocookie.com/embed/${match}" allowfullscreen></iframe>`;else if(/\.(mp4|webm)(\?|$)/i.test(i.video))video=`<video class="video" controls src="${esc(i.video)}"></video>`;else video=`<a class="button" href="${esc(i.video)}" target="_blank" rel="noopener">Open video lecture ↗</a>`;}catch{}}
return before+`<div class="panel">${video}${i.reading?`<p style="margin-top:15px"><a class="button" target="_blank" rel="noopener" href="${esc(i.reading)}">Open reading material ↗</a></p>`:''}${!data.instructor?`<div class="notice" style="margin-top:20px">After reading and viewing the materials, mark this lecture as viewed.</div>${b('✓ Mark as viewed','view',`data-id="${i.id}"`,'primary')}`:'<p class="muted">Use Student view to check the learner experience.</p>'}</div>`;}
if(i.type==='discussion'){const own=data.posts.filter(p=>p.item_id===i.id&&p.enrollment_id===e?.id);const locked=!data.instructor&&i.postFirst&&!own.some(p=>!p.parent_id);return before+`${data.instructor?b('Open grading workspace','review',`data-item="${i.id}"`,'primary'):''}<div class="panel"><h3>Discussion thread</h3>${locked?'<div class="notice">Post your initial response before viewing classmates’ posts.</div>':''}${data.posts.filter(p=>p.item_id===i.id&&!p.parent_id).map(p=>`<article class="post"><div class="meta"><strong>${esc(p.name)}</strong><span>${fmt(p.created_at)}</span></div><div class="prose">${esc(p.body)}</div>${data.posts.filter(r=>r.parent_id===p.id).map(r=>`<div class="post reply"><div class="meta"><strong>${esc(r.name)}</strong><span>${fmt(r.created_at)}</span></div><div class="prose">${esc(r.body)}</div></div>`).join('')}${!data.instructor&&p.enrollment_id!==e.id?b('Reply','reply',`data-parent="${p.id}" data-item="${i.id}"`):''}</article>`).join('')}${!data.instructor?`<h3>Your initial post</h3><textarea id="post-body" aria-label="Your initial discussion post" maxlength="10000" placeholder="Share your reasoning…"></textarea><div class="actions" style="margin-top:12px">${b('Post response','post',`data-id="${i.id}"`,'primary')}<small>${i.replies||0} peer replies required</small></div>`:''}</div>${feedback(s)}`;}
if(i.type==='assignment'){if(data.instructor)return before+`${b('Open grading workspace','review',`data-item="${i.id}"`,'primary')}<div class="panel" style="margin-top:20px"><h3>Class submissions</h3>${data.enrollments.filter(e=>e.active).map(e=>`<div class="list-item"><div class="body">${esc(e.name)}</div>${itemStatus(i,e.id)}${b('Review','review',`data-item="${i.id}" data-student="${e.id}"`)}</div>`).join('')}</div>`;
const f=data.files.find(f=>f.id===s?.answer?.file);return before+`<div class="panel"><h2>Your submission</h2>${s?.submitted_at?`<div class="notice">Submission received ${fmt(s.submitted_at)} · Attempt ${s.attempt}. You can revise and resubmit; a revised submission requires grading again.</div>`:''}<form id="assignment-form" data-item="${i.id}">${i.format==='worksheet'?i.fields.map((field,n)=>`<label>${esc(field)}</label><textarea name="field-${n}" aria-label="${esc(field)}">${esc(s?.answer?.fields?.[n]||'')}</textarea>`).join(''):`<label for="essay-text">Essay response</label><textarea id="essay-text" name="text" style="min-height:260px">${esc(s?.answer?.text||'')}</textarea>`}<label for="submission-file">Or attach a document (up to 2 MB)</label><input type="file" id="submission-file" accept=".pdf,.docx,.txt,.png,.jpg,.jpeg"><p id="attachment-name" class="muted">${f?esc(f.name):'PDF, Word, text, or image'}</p><div class="actions" style="margin-top:20px">${!s||s.status==='draft'?b('Save draft','draft',`data-id="${i.id}"`):''}${b(s&&s.status!=='draft'?'Resubmit assignment':'Submit assignment','submit',`data-id="${i.id}"`,'primary')}</div><p class="save-state" style="margin-top:12px">Drafts save when you select Save draft. Submitted work is stored in your class record.</p></form></div>${feedback(s)}`;}
if(i.type==='quiz'){if(data.instructor)return before+`<div class="panel"><p>${i.questions.length} questions · ${i.timeLimit||'No'} minute time limit · ${i.attempts} attempts</p>${b('Open grading workspace','review',`data-item="${i.id}"`,'primary')}<details><summary>Question and answer key</summary>${i.questions.map(q=>`<div class="question"><strong>${esc(q.text)}</strong><p>${q.points} pts · ${q.type}</p><p>${q.type==='essay'?'Instructor review':esc(q.options?.[Number(q.correct)]||q.correct)}</p></div>`).join('')}</details></div>`;
const a=data.attempts.find(a=>a.item_id===i.id&&!a.submitted_at);const used=data.attempts.filter(a=>a.item_id===i.id).length;return before+`<div class="panel"><div class="row">${badge(i.question_count+' questions')}${badge(i.attempts+' attempts allowed')}${badge((i.timeLimit||'No')+' minute limit')}<span class="timer" id="quiz-timer"></span></div>${a?`<form id="quiz-form" data-attempt="${a.id}">${a.questions.map((q,n)=>`<div class="question"><div class="title-row"><h3>${n+1}. ${esc(q.text)}</h3>${badge(q.points+' pts')}</div>${['choice','truefalse'].includes(q.type)?q.options.map((o,j)=>`<label class="check"><input type="radio" name="${q.id}" value="${j}" ${String(a.answer?.[q.id])===String(j)?'checked':''}>${esc(o)}</label>`).join(''):`<textarea name="${q.id}" aria-label="${esc(q.text)}">${esc(a.answer?.[q.id]||'')}</textarea>`}</div>`).join('')}<div class="actions">${b('Save answers','quiz-save',`data-id="${i.id}"`)}${b('Submit quiz','quiz-submit',`data-id="${i.id}"`,'primary')}</div><p class="save-state" id="quiz-save-state" style="margin-top:12px">Answers save automatically every 15 seconds. The timer continues if you leave this page.</p></form>`:`<p style="margin-top:18px">${used} of ${i.attempts} attempts used. The most recent submitted attempt counts toward your grade.</p>${used<i.attempts?b(used?'Start another attempt':'Take the quiz','quiz-start',`data-id="${i.id}"`,'primary'):badge('All attempts used','gold')}`}</div>${feedback(s)}${data.attempts.filter(a=>a.item_id===i.id&&a.submitted_at).map(a=>`<div class="card"><h3>Attempt ${a.number}</h3><small>Submitted ${fmt(a.submitted_at)}</small><p>Automatic question score: ${a.score} points. Written responses may still need instructor review.</p></div>`).join('')}`;}}
function feedback(s){if(!s||!s.posted)return s?.status==='submitted'||s?.status==='graded'?'<div class="notice">Your work is awaiting grading or release. Feedback will appear here when your instructor posts the grade.</div>':'';return `<div class="panel"><h3>Instructor feedback</h3><p><strong>${s.score??'Excused'} points</strong></p><div class="prose">${esc(s.feedback||'No written feedback provided.')}</div>${s.rubric?.map(r=>`<p>${esc(r.title)}: ${r.score} / ${r.points}</p>`).join('')||''}</div>`;}
function grades(){if(gradeItem&&data.instructor)return review();const is=data.course.data.items.filter(i=>i.published&&i.type!=='lecture');if(!data.instructor){const e=student(),s=state(e);return `${heading('Grades','Your scores and instructor feedback.')}<div class="stats"><div class="panel"><small>Current grade · graded work</small><div class="stat">${percent(s.current)}</div></div><div class="panel"><small>Final grade · ungraded work counts as zero</small><div class="stat">${percent(s.final)}</div></div><div class="panel"><small>Completion status</small><h3>${esc(s.status.replaceAll('_',' '))}</h3></div></div><div class="module">${is.map(i=>`<div class="list-item"><div class="body">${b(esc(i.title),'item',`data-id="${i.id}"`,'link')}<small>${groups[i.type]} · ${fmt(i.due)}</small></div>${itemStatus(i)}</div>`).join('')}</div>`;}
return `${heading('Gradebook','Review submissions, enter scores, and release feedback.',b('Export gradebook CSV','export','data-format="gradebook-csv"'))}<div class="notice">Select a grade cell to open the grading workspace. Current grades include released, graded work. Final grades count ungraded published activities as zero. Excused work is excluded.</div><div class="table-scroll"><table><thead><tr><th>Student</th>${is.map(i=>`<th>${b(esc(i.title),'review',`data-item="${i.id}"`,'link')}<br><small>${i.points} pts · ${groups[i.type]}</small></th>`).join('')}<th>Current</th><th>Final</th><th>Completion</th></tr></thead><tbody>${data.enrollments.map(e=>{const s=state(e);return `<tr><td><strong>${esc(e.name)}</strong><br><small>${esc(e.external_id)}${!e.active?' · Inactive':''}</small></td>${is.map(i=>{const ss=sub(i.id,e.id);return `<td>${b(ss?.status==='excused'?'EX':ss?.score!==null&&ss?.score!==undefined?ss.score+(ss.posted?'':' ◉'):ss?.status==='submitted'?'Review':ss?.status==='draft'?'Draft':'—','review',`data-item="${i.id}" data-student="${e.id}"`,'score-button')}<br><small>${ss?.submitted_at&&i.due&&Date.parse(ss.submitted_at)>Date.parse(i.due)?'Late':ss?'':i.due&&Date.now()>Date.parse(i.due)?'Missing':''}</small></td>`;}).join('')}<td>${percent(s.current)}</td><td>${percent(s.final)}</td><td>${badge(s.status.replaceAll('_',' '),s.status==='completed'?'green':'')}</td></tr>`;}).join('')}</tbody></table></div>${!data.enrollments.length?'<div class="empty">Enroll students from the People page.</div>':''}`;}
function review(){const i=data.course.data.items.find(i=>i.id===gradeItem);const es=data.enrollments;gradeStudent||=es[0]?.id;const e=es.find(e=>e.id===gradeStudent);if(!e)return heading('Grading workspace','Enroll students to review their submissions.',b('← Gradebook','grade-back'));const s=sub(i.id,e.id);const answer=s?.answer||{};const isQuiz=i.type==='quiz';const questions=answer.snapshot?.questions||i.questions||[];const f=data.files.find(f=>f.id===answer.file);return `${heading('Grading workspace',i.title,b('← Gradebook','grade-back'))}<div class="panel row"><label style="margin:0" for="grading-student">Student</label><select id="grading-student" style="max-width:350px">${es.map(e=>`<option value="${e.id}" ${e.id===gradeStudent?'selected':''}>${esc(e.name)}</option>`).join('')}</select>${b('Previous','grade-prev')}${b('Next','grade-next')}<span>${itemStatus(i,e.id)}</span></div><div class="review"><section><div class="panel"><h2>${esc(e.name)}’s work</h2><p class="muted">${s?.submitted_at?'Submitted '+fmt(s.submitted_at)+' · Attempt '+s.attempt:'No submission received'}</p>${i.type==='discussion'?data.posts.filter(p=>p.enrollment_id===e.id&&p.item_id===i.id).map(p=>`<article class="post"><small>${p.parent_id?'Peer reply':'Initial post'} · ${fmt(p.created_at)}</small><div class="prose">${esc(p.body)}</div></article>`).join(''):isQuiz?`<p>Automatically earned: <strong>${answer.auto_score??0}</strong> points. Enter the combined objective and written-response score.</p>${questions.map(q=>`<div class="question"><h3>${esc(q.text)}</h3><p>${q.points} points · ${q.type}</p><div class="prose">Response: ${esc(q.options?.[Number(answer.responses?.[q.id])]||answer.responses?.[q.id]||'No response')}</div><p class="muted">${q.type==='essay'?'Instructor review required':'Answer key: '+esc(q.options?.[Number(q.correct)]||q.correct)}</p></div>`).join('')}`:answer.fields?answer.fields.map((v,n)=>`<h3>${esc(i.fields?.[n]||'Response '+(n+1))}</h3><div class="prose" style="margin-bottom:25px">${esc(v)}</div>`).join(''):`<div class="prose">${esc(answer.text||'')}</div>`}${f?`<div class="notice">Attached file: ${esc(f.name)} ${b('Download','file',`data-file="${f.id}"`)}</div>`:''}</div><div class="panel"><h3>Assignment instructions</h3><div class="prose">${esc(i.body)}</div></div></section><aside><form id="grade-form"><h2>Assessment</h2><label for="grade-score">Score / ${i.points}</label><input id="grade-score" name="score" type="number" min="0" max="${i.points}" step="0.01" value="${s?.score??answer.auto_score??''}"><label class="check"><input name="excused" type="checkbox" ${s?.status==='excused'?'checked':''}> Excuse this activity</label>${i.rubric?.length?`<details open><summary>Rubric</summary>${i.rubric.map((r,n)=>`<div class="rubric"><span>${esc(r.title)}<br><small>${r.points} possible</small></span><input class="rubric-score" name="rubric-${n}" aria-label="${esc(r.title)} score" type="number" min="0" max="${r.points}" step="0.01" value="${s?.rubric?.[n]?.score??''}"></div>`).join('')}${b('Use rubric total','rubric-total')}</details>`:''}<label for="grade-feedback">Feedback</label><textarea id="grade-feedback" name="feedback" maxlength="10000">${esc(s?.feedback||'')}</textarea><label class="check"><input name="posted" type="checkbox" ${s?.posted?'checked':''}> Release grade to student</label><p class="muted"><small>Held grades remain private and do not complete the activity until released.</small></p>${b('Save grade','grade','','primary')} ${b('Save & next','grade-next-save')}<p class="save-state" id="grade-save-status"></p></form></aside></div>`;}
function people(){return `${heading('People','Manage your roster. Each class allows up to 20 active students.',b('+ Enroll student','enroll','','primary'))}<div class="notice">Enroll the same email address the student uses to sign in. External student IDs let you match records in your separate database. Student sign-in: <strong>${esc(location.origin)}/lms.html</strong></div><div class="table-scroll"><table><thead><tr><th>Student</th><th>Email</th><th>External ID</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.enrollments.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.email)}</td><td>${esc(e.external_id)}</td><td>${badge(e.active?'Active':'Inactive',e.active?'green':'')}</td><td>${b('Edit','edit-enrollment',`data-id="${e.id}"`)} ${e.active?b('Student view','preview',`data-id="${e.id}"`):''}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="margin-top:15px">${data.enrollments.filter(e=>e.active).length} of 20 active seats used.</p>`;}
function completion(){return `${heading('Completion & exports','Transfer student completion records into your separate database.',b('Export CSV','export','data-format="completion-csv"','primary')+' '+b('Export JSON','export','data-format="completion-json"'))}<div class="notice">Completion requires every published required lecture to be viewed, required work to be submitted and graded, required discussion participation to be met, grades to be released, and the final grade to meet ${data.course.data.pass}%. Optional graded activities still affect the final grade.</div><div class="table-scroll"><table><thead><tr><th>Student</th><th>External ID</th><th>Required activities</th><th>Final grade</th><th>Status</th><th>Completed</th></tr></thead><tbody>${data.enrollments.map(e=>{const s=state(e);return `<tr><td>${esc(e.name)}${e.active?'':' (inactive)'}</td><td>${esc(e.external_id)}</td><td>${s.done} / ${s.required}<div class="progress"><span style="width:${s.progress}%"></span></div></td><td>${percent(s.final)}</td><td>${badge(s.status.replaceAll('_',' '),s.status==='completed'?'green':'gold')}</td><td>${s.status==='completed'&&e.completed_at?fmt(e.completed_at):'—'}</td></tr>`;}).join('')}</tbody></table></div><div class="panel" style="margin-top:20px"><h3>Database import fields</h3><p>Stable student and class identifiers, external student ID, name, email, course code, enrollment status, completion status, progress, current and final scores, passing score, enrollment date, completion date, update date, and export date.</p><p class="muted">UTF-8 CSV or JSON · Schema version 1.0 · Dates use ISO 8601 UTC. No submission text or discussion content is included in completion exports.</p></div>`;}
function settings(){const c=data.course.data;return `${heading('Course settings','Edit your classroom and grading rules.',b('Duplicate as new class','duplicate')+' '+b('Archive class','archive','','danger'))}<form id="settings-form" class="panel"><div class="two"><div><label>Course title</label><input name="title" required maxlength="200" value="${esc(c.title)}"><label>Course code</label><input name="code" value="${esc(c.code)}"><label>Class offering name</label><input name="name" required maxlength="200" value="${esc(data.course.name)}"></div><div><label>Course description</label><textarea name="description">${esc(c.description)}</textarea><label>Passing score (%)</label><input name="pass" type="number" min="0" max="100" value="${c.pass}"></div></div><label class="check"><input type="checkbox" name="published" ${c.published?'checked':''}> Publish class to enrolled students</label><label class="check"><input type="checkbox" name="weighted" ${c.weighted?'checked':''}> Use weighted assignment categories</label><div class="two">${Object.entries(groups).map(([k,v])=>`<div><label>${v} weight (%)</label><input type="number" name="weight-${k}" min="0" max="100" value="${c.weights[k]}"></div>`).join('')}</div><p class="muted" style="margin-top:15px">Weights must total 100%. When weighting is off, grades use total earned points divided by total possible points. Empty categories are excluded and remaining weights are normalized.</p>${b('Save settings','save-settings','','primary')}</form><div class="panel"><h3>Recent grading changes</h3>${data.audit.slice(0,10).map(a=>`<p><small>${fmt(a.created_at)}</small> · ${esc(a.action)} · Score: ${esc(a.detail?.score??'—')} · ${a.detail?.posted?'Released':'Held'}</p>`).join('')||'<p class="muted">No grades changed yet.</p>'}</div>`;}
function navigateItem(id){itemId=id;const i=data.course.data.items.find(i=>i.id===id);page={lecture:'Lectures',assignment:'Assignments',discussion:'Discussions',quiz:'Quizzes'}[i.type];gradeItem=null;render();}
async function saveCourse(d,name=data.course.name){cleanCourse(d);data=await call('save',{course:data.course.id,version:data.course.version,data:d,name});render();}
function editItem(id,type='assignment'){const d=structuredClone(data.course.data);let i=d.items.find(i=>i.id===id);const fresh=!i;if(!i)i={id:uid(),module:d.modules[0].id,type,title:'',body:'',points:type==='lecture'?0:20,published:false,required:true,due:null,format:'essay',fields:['Response'],reading:'',video:'',replies:1,postFirst:false,rubric:[],attempts:2,timeLimit:15,questions:[]};dialog(fresh?'Add activity':'Edit activity',`<label>Activity type</label><select name="type" id="item-type" ${fresh?'':'disabled'}>${['lecture','assignment','discussion','quiz'].map(t=>`<option ${i.type===t?'selected':''}>${t}</option>`).join('')}</select><label>Title</label><input name="title" required maxlength="200" value="${esc(i.title)}"><label>Module</label><select name="module">${d.modules.map(m=>`<option value="${m.id}" ${m.id===i.module?'selected':''}>${esc(m.title)}</option>`).join('')}</select><label>Instructions / lecture content</label><textarea name="body" style="min-height:180px">${esc(i.body)}</textarea><div class="two"><div><label>Points (0 for lectures)</label><input name="points" type="number" min="0" max="10000" value="${i.points}"></div><div><label>Due date</label><input name="due" type="datetime-local" value="${i.due?localDate(i.due):''}"></div></div><label class="check"><input name="published" type="checkbox" ${i.published?'checked':''}> Published</label><label class="check"><input name="required" type="checkbox" ${i.required?'checked':''}> Required for completion</label><details ${i.type==='lecture'?'open':''}><summary>Lecture materials</summary><label>Reading URL</label><input type="url" name="reading" value="${esc(i.reading)}"><label>Video URL (YouTube, MP4, or video page)</label><input type="url" name="video" value="${esc(i.video)}"></details><details ${i.type==='assignment'?'open':''}><summary>Assignment format</summary><label>Submission format</label><select name="format"><option value="essay" ${i.format!=='worksheet'?'selected':''}>Essay / file upload</option><option value="worksheet" ${i.format==='worksheet'?'selected':''}>Worksheet fields</option></select><label>Worksheet prompts (one per line)</label><textarea name="fields">${esc(i.fields?.join('\n')||'')}</textarea></details><details ${i.type==='discussion'?'open':''}><summary>Discussion settings</summary><label>Required replies to classmates</label><input type="number" name="replies" min="0" max="20" value="${i.replies??1}"><label class="check"><input name="postFirst" type="checkbox" ${i.postFirst?'checked':''}> Post before seeing classmates’ responses</label></details><details ${i.type==='quiz'?'open':''}><summary>Quiz settings & questions</summary><div class="two"><div><label>Time limit (minutes; 0 = untimed)</label><input name="timeLimit" type="number" min="0" max="240" value="${i.timeLimit??15}"></div><div><label>Attempts</label><input name="attempts" type="number" min="1" max="10" value="${i.attempts??2}"></div></div><div id="question-editor">${(i.questions||[]).map(questionEditor).join('')}</div>${b('+ Add question','add-question')}</details><details ${i.rubric?.length?'open':''}><summary>Rubric</summary><p class="muted">One criterion per line: title | points. Criterion points should total the activity points.</p><textarea name="rubric">${esc(i.rubric?.map(r=>r.title+' | '+r.points).join('\n')||'')}</textarea></details>`,async f=>{i.type=fresh?f.get('type'):i.type;for(const k of ['title','module','body','format','reading','video'])i[k]=String(f.get(k)||'');i.points=Number(f.get('points'));i.due=f.get('due')?new Date(f.get('due')).toISOString():null;i.published=f.has('published');i.required=f.has('required');i.fields=String(f.get('fields')).split('\n').map(s=>s.trim()).filter(Boolean);i.replies=Number(f.get('replies'));i.postFirst=f.has('postFirst');i.timeLimit=Number(f.get('timeLimit'));i.attempts=Number(f.get('attempts'));i.rubric=String(f.get('rubric')||'').split('\n').filter(s=>s.trim()).map(line=>{const [title,points]=line.split('|');return {title:title.trim(),points:Number(points)};});if(i.rubric.some(r=>!r.title||!Number.isFinite(r.points)||r.points<=0)||i.rubric.length&&Math.abs(i.rubric.reduce((n,r)=>n+r.points,0)-i.points)>.01)throw Error('Rubric points must be positive and total the activity points.');if(i.type==='quiz')i.questions=[...modal.querySelectorAll('.q-editor')].map(el=>({id:el.dataset.id,text:el.querySelector('[data-q=text]').value,type:el.querySelector('[data-q=type]').value,points:Number(el.querySelector('[data-q=points]').value),options:el.querySelector('[data-q=options]').value.split('\n').filter(Boolean),correct:el.querySelector('[data-q=correct]').value}));if(i.type==='assignment'&&i.format==='worksheet'&&!i.fields.length)throw Error('Add worksheet prompts.');if(fresh)d.items.push(i);await saveCourse(d);toast('Activity saved.');});}
function localDate(iso){const dt=new Date(iso);return new Date(dt-dt.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function questionEditor(q={id:uid(),type:'choice',text:'',points:10,options:['Option A','Option B'],correct:'0'}){return `<div class="question q-editor" data-id="${q.id}"><label>Question</label><textarea data-q="text">${esc(q.text)}</textarea><div class="two"><div><label>Type</label><select data-q="type">${['choice','truefalse','short','essay'].map(t=>`<option ${q.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label>Points</label><input type="number" min="1" data-q="points" value="${q.points}"></div></div><label>Options (one per line; choice / truefalse)</label><textarea data-q="options">${esc(q.options?.join('\n')||'')}</textarea><label>Correct answer (choice index starts at 0; short answers separated by |)</label><input data-q="correct" value="${esc(q.correct)}">${b('Remove question','remove-question','','danger')}</div>`;}
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function assignmentSave(id,submit){const i=data.course.data.items.find(i=>i.id===id),s=sub(id),form=document.querySelector('#assignment-form');const fields=new FormData(form);let file=s?.answer?.file;const attached=document.querySelector('#submission-file').files[0];if(attached){if(attached.size>2*1024*1024)throw Error('Choose a file no larger than 2 MB.');const mime=attached.type||({pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',txt:'text/plain',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg'}[attached.name.split('.').at(-1).toLowerCase()]);if(!mime)throw Error('Unsupported file type.');const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(attached);});file=(await call('file-add',{course:data.course.id,...(preview?{preview}:{}),item:id,name:attached.name,mime,data:encoded})).id;}
const answer=i.format==='worksheet'?{fields:i.fields.map((_,n)=>String(fields.get('field-'+n)||''))}:{text:String(fields.get('text')||'')};if(file)answer.file=file;await mutation(submit?'submit':'draft',{item:id,answer,version:s?.version??null});toast(submit?'Submission received. Your instructor can now review it.':'Draft saved.');}
function quizAnswer(){const f=document.querySelector('#quiz-form');if(!f)return null;return Object.fromEntries(new FormData(f));}
async function saveQuiz(submit=false,silent=false){const f=document.querySelector('#quiz-form');if(!f)return;const answer=quizAnswer();const out=await call(submit?'quiz-submit':'quiz-save',{course:data.course.id,...(preview?{preview}:{}),item:itemId,attempt:f.dataset.attempt,answer});if(submit){data=out;render();toast('Quiz submitted.');}else{data=out;const label=document.querySelector('#quiz-save-state');if(label)label.textContent='Answers saved '+new Date().toLocaleTimeString()+'.';if(!out.attempts.some(a=>a.id===f.dataset.attempt&&!a.submitted_at)){render();toast('Time expired. Your saved answers were submitted.');}}}
function startTimer(){const a=data.attempts.find(a=>a.item_id===itemId&&!a.submitted_at);if(!a)return;let ticks=0,expired=false,saving=false;timer=setInterval(async()=>{const label=document.querySelector('#quiz-timer');const ms=a.deadline?Math.max(0,Date.parse(a.deadline)-Date.now()):null;if(label)label.textContent=ms===null?'Untimed':Math.floor(ms/60000)+':'+String(Math.floor(ms/1000)%60).padStart(2,'0')+' remaining';ticks++;try{if(ms===0&&!expired){expired=true;await saveQuiz(true,true);}else if(ticks%15===0&&!saving){saving=true;await saveQuiz(false,true);saving=false;}}catch(e){saving=false;const s=document.querySelector('#quiz-save-state');if(s)s.textContent='Save interrupted. Keep this page open and retry Save answers.';}},1000);}
async function saveGrade(next=false){const i=data.course.data.items.find(i=>i.id===gradeItem),s=sub(i.id,gradeStudent),f=new FormData(document.querySelector('#grade-form'));const rubric=(i.rubric||[]).map((r,n)=>({...r,score:Number(f.get('rubric-'+n))}));if(rubric.some(r=>r.score<0||r.score>r.points))throw Error('Rubric scores must be within their point ranges.');await mutation('grade',{item:i.id,enrollment:gradeStudent,version:s?.version??0,status:f.has('excused')?'excused':'graded',score:f.get('score')===''?null:Number(f.get('score')),posted:f.has('posted'),feedback:String(f.get('feedback')||''),rubric});toast('Grade saved to the gradebook.');if(next){gradeStudent=data.enrollments[(data.enrollments.findIndex(e=>e.id===gradeStudent)+1)%data.enrollments.length].id;render();}}
async function handle(button){const a=button.dataset.action;
if(a==='close-modal'){modal.close();return;}if(a==='add-question'){modal.querySelector('#question-editor').insertAdjacentHTML('beforeend',questionEditor());return;}if(a==='remove-question'){button.closest('.q-editor').remove();return;}
if(a==='demo'){demo=true;history.replaceState(null,'','/lms.html?demo=1');await loadList();await openCourse(courses[0].id);return;}if(a==='exit-demo'){demo=false;data=null;courses=[];history.replaceState(null,'','/lms.html');if(session)await loadList();else render();return;}if(a==='reset-demo'){dialog('Reset pilot preview','<p>This resets only the fictional pilot data stored in this browser.</p>',async()=>{resetDemo();await loadList();await openCourse(courses[0].id);});return;}
if(a==='logout'){if(!demo)await auth.auth.signOut();session=null;demo=false;data=null;history.replaceState(null,'','/lms.html');render();return;}
if(a==='signup'){const f=new FormData(document.querySelector('#login-form'));if(!f.get('email')||String(f.get('password')).length<8)throw Error('Enter your email and a password of at least 8 characters.');const {error}=await auth.auth.signUp({email:f.get('email'),password:f.get('password'),options:{emailRedirectTo:location.origin+'/lms.html'}});if(error)throw error;document.querySelector('#auth-status').textContent='Check your email for account confirmation, then sign in. Your instructor must enroll this email in a class.';return;}
if(a==='forgot'){const email=document.querySelector('#email').value;if(!email)throw Error('Enter your email address first.');const {error}=await auth.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/lms.html'});if(error)throw error;document.querySelector('#auth-status').textContent='If your account exists, a password reset link will be sent to your email.';return;}
if(a==='dashboard'){await loadList();return;}if(a==='open'){await openCourse(button.dataset.id);return;}if(a==='refresh'){await reload();return;}if(a==='page'){if(document.querySelector('#quiz-form'))await saveQuiz();page=button.dataset.page;itemId=null;gradeItem=null;render();return;}if(a==='back'){if(document.querySelector('#quiz-form'))await saveQuiz();itemId=null;render();return;}if(a==='item'){navigateItem(button.dataset.id);return;}
if(a==='settings-link'){page='Settings';render();return;}
if(a==='create'||a==='duplicate'){dialog(a==='create'?'Create class':'Duplicate as a new class','<label>Class offering name</label><input name="name" required maxlength="200" placeholder="Fall cohort · Critical Thinking"><p class="muted" style="margin-top:15px">'+(a==='create'?'Starts with the Critical Thinking pilot course. Edit all materials from Modules and Settings.':'Copies course materials and settings with a fresh roster, submissions, and gradebook.')+'</p>',async f=>{const d=a==='create'?seed():structuredClone(data.course.data);d.published=false;d.template_id=data?.course.data.template_id||data?.course.id||uid();const r=await call('create',{name:String(f.get('name')),data:cleanCourse(d)});await loadList();await openCourse(r.id);toast('Class created.');});return;}
if(a==='preview'){const id=button.dataset.id;if(id){preview=id;data=await call('get',{course:data.course.id,preview});itemId=null;page='Home';render();return;}if(!data.enrollments.some(e=>e.active))throw Error('Enroll a student first, or use the pilot preview from the sign-in page.');dialog('Choose a student view','<label>Student</label><select name="student">'+data.enrollments.filter(e=>e.active).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')+'</select><div class="notice" style="margin-top:15px">This view uses the selected student’s actual class record. Submissions and progress made here are saved to that record.</div>',async f=>{preview=String(f.get('student'));data=await call('get',{course:data.course.id,preview});page='Home';itemId=null;render();});return;}
if(a==='leave-preview'){preview=null;await reload();page='Home';itemId=null;render();return;}
if(a==='add-item'){editItem(null,button.dataset.type);return;}if(a==='edit-item'){editItem(button.dataset.id);return;}
if(a==='module'||a==='edit-module'){const d=structuredClone(data.course.data);const m=d.modules.find(m=>m.id===button.dataset.id)||{id:uid(),title:'',description:'',sequential:false};dialog('Module settings',`<label>Title</label><input name="title" required value="${esc(m.title)}"><label>Description</label><textarea name="description">${esc(m.description)}</textarea><label class="check"><input name="sequential" type="checkbox" ${m.sequential?'checked':''}> Complete required activities sequentially</label><p class="muted">Learners must view or submit preceding required activities before using the next activity in this module.</p>`,async f=>{m.title=String(f.get('title'));m.description=String(f.get('description'));m.sequential=f.has('sequential');if(!d.modules.some(x=>x.id===m.id))d.modules.push(m);await saveCourse(d);});return;}
if(a==='announcement'){dialog('Add announcement','<label>Title</label><input name="title" required><label>Message</label><textarea name="body" required></textarea>',async f=>{const d=structuredClone(data.course.data);d.announcements.unshift({id:uid(),title:String(f.get('title')),body:String(f.get('body')),date:new Date().toISOString()});await saveCourse(d);});return;}
if(a==='enroll'){dialog('Enroll student','<label>Student name</label><input name="name" required maxlength="200"><label>Email used for sign-in</label><input name="email" type="email" required><label>External student ID</label><input name="external_id" maxlength="200"><p class="muted" style="margin-top:12px">Give the student the sign-in URL shown on the People page. No invitation email is sent by this action.</p>',async f=>{await mutation('enroll',Object.fromEntries(f));toast('Student enrolled.');});return;}
if(a==='edit-enrollment'){const e=data.enrollments.find(e=>e.id===button.dataset.id);dialog('Enrollment settings',`<p>${esc(e.name)} · ${esc(e.email)}</p><label>External student ID</label><input name="external_id" value="${esc(e.external_id)}"><label class="check"><input name="active" type="checkbox" ${e.active?'checked':''}> Active enrollment</label>`,async f=>mutation('enrollment',{enrollment:e.id,external_id:String(f.get('external_id')),active:f.has('active')}));return;}
if(a==='save-settings'){const f=new FormData(document.querySelector('#settings-form')),d=structuredClone(data.course.data);for(const k of ['title','code','description'])d[k]=String(f.get(k));d.pass=Number(f.get('pass'));d.published=f.has('published');d.weighted=f.has('weighted');for(const k of Object.keys(groups))d.weights[k]=Number(f.get('weight-'+k));await saveCourse(d,String(f.get('name')));toast('Course settings saved.');return;}
if(a==='archive'){dialog('Archive class','<p>Hide this class from the dashboard. Student records remain stored.</p>',async()=>{await call('archive',{course:data.course.id});await loadList();});return;}
if(a==='view'){await mutation('view',{item:button.dataset.id});toast('Lecture marked viewed.');return;}
if(a==='post'){const body=document.querySelector('#post-body').value.trim();if(!body)throw Error('Write your response first.');await mutation('post',{item:button.dataset.id,body});toast('Discussion response posted.');return;}
if(a==='reply'){dialog('Reply to classmate','<label>Your reply</label><textarea name="body" required maxlength="10000"></textarea>',async f=>{await mutation('post',{item:button.dataset.item,parent:button.dataset.parent,body:String(f.get('body'))});toast('Reply posted.');});return;}
if(a==='draft'||a==='submit'){await assignmentSave(button.dataset.id,a==='submit');return;}
if(a==='quiz-start'){await mutation('quiz-start',{item:button.dataset.id});return;}if(a==='quiz-save'||a==='quiz-submit'){await saveQuiz(a==='quiz-submit');return;}
if(a==='review'){page='Grades';gradeItem=button.dataset.item;gradeStudent=button.dataset.student||data.enrollments[0]?.id;itemId=null;render();return;}
if(a==='grade-back'){gradeItem=null;render();return;}if(a==='grade-prev'||a==='grade-next'){const index=data.enrollments.findIndex(e=>e.id===gradeStudent);gradeStudent=data.enrollments[(index+(a==='grade-next'?1:-1)+data.enrollments.length)%data.enrollments.length].id;render();return;}
if(a==='rubric-total'){document.querySelector('#grade-score').value=[...document.querySelectorAll('.rubric-score')].reduce((n,el)=>n+Number(el.value||0),0);return;}if(a==='grade'||a==='grade-next-save'){await saveGrade(a==='grade-next-save');return;}
if(a==='file'){const f=await call('file-get',{course:data.course.id,...(preview?{preview}:{}),file:button.dataset.file});download(f.name,Uint8Array.from(atob(f.data),c=>c.charCodeAt(0)),f.mime);return;}
if(a==='export'){const format=button.dataset.format;if(demo){const rows=completionRows(data);if(format==='completion-json')download('completion-statuses.json',JSON.stringify({schema_version:'1.0',records:rows},null,2),'application/json');else if(format==='completion-csv')download('completion-statuses.csv',csv(rows),'text/csv');else{const is=data.course.data.items.filter(i=>i.published&&i.type!=='lecture');const columns=['student_id','external_student_id','student_name',...is.map(i=>i.title),'final_score_percent'];rows.forEach(r=>{const e=data.enrollments.find(e=>(e.user_id||e.id)===r.student_id);is.forEach(i=>r[i.title]=sub(i.id,e.id)?.score??'');});download('gradebook.csv',csv(rows,columns),'text/csv');}}else{const out=await call(format,{course:data.course.id});download(format==='completion-json'?'completion-statuses.json':format==='gradebook-csv'?'gradebook.csv':'completion-statuses.csv',format==='completion-json'?JSON.stringify(out,null,2):out.text,format==='completion-json'?'application/json':'text/csv');}toast('Export downloaded.');return;}}
document.addEventListener('click',async ev=>{const button=ev.target.closest('[data-action]');if(!button||busy)return;busy=true;button.disabled=true;try{await handle(button);}catch(e){toast(e.message);}finally{busy=false;button.disabled=false;}});
document.addEventListener('change',ev=>{if(ev.target.id==='grading-student'){gradeStudent=ev.target.value;render();}if(ev.target.id==='submission-file'){const f=ev.target.files[0];document.querySelector('#attachment-name').textContent=f?f.name:'No new attachment';}});
auth.auth.onAuthStateChange((event,s)=>{session=s;if(event==='PASSWORD_RECOVERY')setTimeout(()=>dialog('Set a new password','<label>New password</label><input type="password" name="password" minlength="8" required autocomplete="new-password">',async f=>{const {error}=await auth.auth.updateUser({password:String(f.get('password'))});if(error)throw error;toast('Password updated.');await loadList();}),0);});
try{const {data:d}=await auth.auth.getSession();session=d.session;if(demo){await loadList();await openCourse(courses[0].id);}else if(session)await loadList();else render();}catch(e){render();toast(e.message);}
